p='src/orders.js'
s=open(p).read()
s=s.replace('import { reserve } from "./inventory.js";\n','import { reserve } from "./inventory.js";\nimport { percentOf } from "./money.js";\n')
s+='''
const RESTOCKING_RATE = 0.1;

/**
 * The cents to refund for an order, by reason. "damaged" refunds the total, "late" the
 * shipping cost, "changed-mind" the net less a 10% restocking fee. Other reasons refund nothing.
 */
export function refundFor(order, reason) {
  switch (reason) {
    case "damaged":
      return order.total;
    case "late":
      return order.shipping.cost;
    case "changed-mind":
      return order.net - percentOf(order.net, RESTOCKING_RATE);
    default:
      return 0;
  }
}
'''
open(p,'w').write(s)
p='test/orders.test.js'
s=open(p).read()
s=s.replace('import { placeOrder }','import { placeOrder, refundFor }')
s+='''
test("refunds depend on the reason", () => {
  const order = { net: 26905, total: 26905 + 1950 + 5400, shipping: { tier: "freight-express", cost: 5400 } };
  assert.equal(refundFor(order, "damaged"), 34255);
  assert.equal(refundFor(order, "late"), 5400);
  assert.equal(refundFor(order, "changed-mind"), 26905 - 2691);
  assert.equal(refundFor(order, "other"), 0);
  assert.equal(refundFor(order, undefined), 0);
});
'''
open(p,'w').write(s)
